    34→async function DocsPage(_props: PageProps<"/docs">) {
    35→  const { t, locale } = await getI18n();
    36→  const docs = await getDocs(undefined, locale);
    37→
    38→  const sortedDocs = [...docs].sort((a, b) => {
    39→    if (a.attributes.order !== undefined && b.attributes.order !== undefined) {
    40→      return a.attributes.order - b.attributes.order;
    41→    }
    42→    return a.attributes.title.localeCompare(b.attributes.title);
